    CONSTRAINT ck_loan_status CHECK (status IN ('draft', 'reserved', 'issued', 'return_pending', 'returned', 'lost', 'cancelled')),
    CONSTRAINT ck_loan_1 CHECK (due_on IS NULL OR issued_on IS NULL OR due_on >= issued_on),
    CONSTRAINT ck_loan_2 CHECK (status IN ('draft','reserved') OR issued_on IS NOT NULL)
);
